INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist eine CI/CD-Pipeline nur für große Teams sinnvoll?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Teams profitieren von Automatisierung"}, {"text": "Ja", "correct": false, "because": "Skalierung ist kein Muss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer CI/CD-Pipeline?', 3, '[{"text": "Automatisierte Bereitstellung", "correct": true, "because": "Schnelle und sichere Releases"}, {"text": "Codeverschleierung", "correct": false, "because": "Nicht primär"}, {"text": "Maximale Speichernutzung", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu einer CI/CD-Pipeline?', 5, '[{"text": "Build-Automatisierung", "correct": true, "because": "Erzeugt ausführbare Artefakte"}, {"text": "Tests", "correct": true, "because": "Sichert Qualität"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}, {"text": "Manuelle Freigabe", "correct": false, "because": "Widerspricht Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CI/CD reduziert manuelle Fehler. b) Es macht Tests überflüssig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests sind zentral"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Einrichtung einer CI/CD-Pipeline?', 4, '[{"text": "Build-Skripte", "correct": false, "because": "Kern der Automatisierung"}, {"text": "Testabdeckung", "correct": false, "because": "Sichert Qualität"}, {"text": "UI-Design", "correct": true, "because": "Kein Pipeline-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine CI/CD-Pipeline auch ohne Git funktioniert?', 2, '[{"text": "Ja", "correct": true, "because": "Andere VCS wie SVN möglich"}, {"text": "Nein", "correct": false, "because": "Git nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool wähle ich für eine flexible CI/CD-Pipeline?', 3, '[{"text": "Jenkins", "correct": true, "because": "Hohe Anpassbarkeit"}, {"text": "Notepad", "correct": false, "because": "Kein CI/CD-Tool"}, {"text": "Ping", "correct": false, "because": "Netzwerkdiagnose"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu einer CI/CD-Pipeline?', 5, '[{"text": "Build", "correct": true, "because": "Erzeugt Artefakte"}, {"text": "Deploy", "correct": true, "because": "Stellt Anwendung bereit"}, {"text": "Design", "correct": false, "because": "Nicht Teil der Pipeline"}, {"text": "Datenbankoptimierung", "correct": false, "because": "Separater Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) CI/CD verkürzt Release-Zyklen. b) Es ist nur für Web-Apps geeignet. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Für alle Softwaretypen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine CI/CD-Pipeline?', 4, '[{"text": "Versionskontrolle", "correct": false, "because": "Basis für Änderungen"}, {"text": "Automatisierte Tests", "correct": false, "because": "Sichert Qualität"}, {"text": "Manuelle Code-Reviews", "correct": true, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist CI nur für Integration da?', 2, '[{"text": "Ja", "correct": true, "because": "Fokus auf kontinuierliche Integration"}, {"text": "Nein", "correct": false, "because": "CD ergänzt Deployment"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools unterstützen CI/CD effektiv?', 4, '[{"text": "GitLab CI", "correct": true, "because": "Integriert und flexibel"}, {"text": "Jenkins", "correct": true, "because": "Vielseitig anpassbar"}, {"text": "Excel", "correct": false, "because": "Kein CI/CD-Tool"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass CI/CD die Entwicklung verlangsamt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Automatisierung beschleunigt"}, {"text": "Ja", "correct": false, "because": "Initialaufwand wird überkompensiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einer CI/CD-Pipeline?', 3, '[{"text": "Testautomatisierung", "correct": true, "because": "Sichert Qualität früh"}, {"text": "Schnelle Builds", "correct": false, "because": "Qualität vor Geschwindigkeit"}, {"text": "Manuelle Freigaben", "correct": false, "because": "Widerspricht Automatisierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) CI/CD braucht Versionskontrolle. b) Es funktioniert ohne Tests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Tests sind essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine CI/CD-Pipeline?', 5, '[{"text": "Schnelle Fehlererkennung", "correct": true, "because": "Tests laufen automatisch"}, {"text": "Konsistente Releases", "correct": true, "because": "Automatisierte Prozesse"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Kein Pipeline-Vorteil"}, {"text": "Manuelle Kontrolle", "correct": false, "because": "Widerspricht CI/CD"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einer CI/CD-Pipeline unwichtig?', 3, '[{"text": "Build-Zeit", "correct": false, "because": "Beeinflusst Effizienz"}, {"text": "Testabdeckung", "correct": false, "because": "Sichert Qualität"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Automatisierung im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine CI/CD-Pipeline auch manuelle Schritte enthalten?', 3, '[{"text": "Ja", "correct": true, "because": "Hybrid möglich, aber weniger ideal"}, {"text": "Nein", "correct": false, "because": "Automatisierung ist Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob GitLab CI auch CD unterstützt?', 2, '[{"text": "Ja", "correct": true, "because": "Umfassendes CI/CD-Tool"}, {"text": "Nein", "correct": false, "because": "CD ist integriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element wähle ich für eine robuste CI/CD-Pipeline?', 4, '[{"text": "Automatisierte Tests", "correct": true, "because": "Sichert Qualität und Stabilität"}, {"text": "Manuelle Builds", "correct": false, "because": "Widerspricht Automatisierung"}, {"text": "Grafische Reports", "correct": false, "because": "Nice-to-have"}]');
